<template>
  <section v-loading="loading" class="exchange-detail">
    <div class="crumb">采购管理　/　不合格品处理　/　采购换货单　/　<b>{{ order.exchange_no }}</b></div>
    <header><div><h1>采购换货单详情</h1><el-button size="small" icon="el-icon-back" @click="$router.push('/purchase/exchanges')">返回列表</el-button><el-button size="small" icon="el-icon-printer" @click="printPage">打印换货单</el-button></div><el-button v-if="nextAction && $can('purchase.exchange.manage')" type="success" size="small" @click="executeNext">下一步：{{ nextAction.label }}　›</el-button></header>
    <div class="steps-scroll"><div class="steps"><div v-for="(step,index) in steps" :key="step.value" class="step-item" :class="{done:stepDone(index),active:order.current_step===step.value}"><i>{{ stepDone(index)?'✓':index+1 }}</i><span>{{ step.label }}<small v-if="stepTime(step.value)">{{ stepTime(step.value) }}</small></span></div></div></div>

    <div class="triple cards">
      <section><h3><i>1</i> 原采购与质量来源</h3><dl><dt>原采购订单</dt><dd>{{ val(order.purchase_order,'purchase_order_no') }}</dd><dt>原到货单</dt><dd>{{ val(order.source_receipt,'receipt_no') }}</dd><dt>{{ isInventoryExchange ? '库存质量事件' : '不合格处理单' }}</dt><dd>{{ isInventoryExchange ? val(order.inventory_quality_event,'event_no') : val(order.handling,'handling_no') }}</dd><dt>供应商</dt><dd>{{ val(order.supplier,'supplier_name') }}</dd><dt>物料</dt><dd>{{ val(order.item,'item_name') }}</dd><dt>数量</dt><dd>{{ qty(order.exchange_base_qty) }} {{ order.base_unit_name_snapshot }}</dd><dt>问题原因</dt><dd>{{ isInventoryExchange ? val(order.inventory_quality_event,'issue_description') : val(order.handling,'defect_reason') }}</dd></dl></section>
      <section><h3><i>2</i> 原货退回信息</h3><dl><template v-if="isInventoryExchange"><dt>退回仓库/库位</dt><dd>{{ order.return_warehouse_name || '--' }} / {{ order.return_location_name || '--' }}</dd><dt>退回序列号</dt><dd>{{ originalSerials }}</dd></template><template v-else><dt>原货所在区域</dt><dd>收货/待验区（未入库）</dd><dt>库存处理</dt><dd>未入库，不占用仓库、库位和库存序列号</dd></template><dt>退回数量</dt><dd>{{ qty(order.returned_base_qty) }} {{ order.base_unit_name_snapshot }}</dd><dt>物流公司</dt><dd>{{ order.return_logistics_company || '--' }}</dd><dt>运单号</dt><dd>{{ order.return_tracking_no || '--' }}</dd><dt>退回时间</dt><dd>{{ dateTime(order.returned_at) }}</dd><dt>供应商收货确认</dt><dd><span v-if="order.supplier_received_at" class="ok">已确认</span><span v-else>--</span> {{ order.supplier_receiver || '' }}</dd><dt>退回/补发凭证</dt><dd class="proof-links"><a v-for="file in order.attachments||[]" :key="file.id" @click="previewProof(file)"><i class="el-icon-view" />{{ file.original_name }}</a><span v-if="!(order.attachments||[]).length">--</span></dd></dl></section>
      <section><h3><i>3</i> 补发与替换品信息</h3><dl><dt>替换品数量</dt><dd>{{ qty(order.exchange_base_qty) }} {{ order.base_unit_name_snapshot }}</dd><dt>供应商补发日期</dt><dd>{{ date(order.replacement_shipped_date) }}</dd><dt>物流公司</dt><dd>{{ order.replacement_logistics_company || '--' }}</dd><dt>运单号</dt><dd>{{ order.replacement_tracking_no || '--' }}</dd><dt>预计到货时间</dt><dd>{{ date(order.replacement_expected_date) }}</dd><dt>替换品到货单</dt><dd><a v-if="order.replacement_receipt_id" @click="$router.push(`/purchase/receipts/${order.replacement_receipt_id}/edit`)">{{ val(order.replacement_receipt,'receipt_no') }}</a><span v-else>--</span></dd><dt>验收状态</dt><dd>{{ replacementStatus }}</dd><template v-if="isInventoryExchange"><dt>替换品序列号</dt><dd>{{ replacementSerials }}</dd></template></dl></section>
    </div>

    <section v-if="isInventoryExchange && order.source_receipt_item && order.source_receipt_item.item && (order.source_receipt_item.item.serial_tracking_mode === 'required' || order.source_receipt_item.item.is_serial_managed)" class="card serial-card"><h3><i>4</i> 原品与替换品编号对应关系</h3><el-table :data="order.serial_links || []" border size="mini"><el-table-column prop="original_serial_no" label="原品序列号" /><el-table-column label="退回状态"><template slot-scope="{row}">{{ row.original_return_status==='supplier_received'?'供应商已收货':row.original_return_status==='returned'?'已退回':'待退回' }}</template></el-table-column><el-table-column prop="replacement_serial_no" label="替换品序列号" /><el-table-column label="替换到货状态"><template slot-scope="{row}">{{ row.replacement_receipt_status==='accepted'?'已验收':'待到货' }}</template></el-table-column><el-table-column label="关联时间"><template slot-scope="{row}">{{ dateTime(row.linked_at) }}</template></el-table-column></el-table></section>

    <div class="double">
      <section class="card amount"><h3><i>{{ isInventoryExchange && order.source_receipt_item && order.source_receipt_item.item && (order.source_receipt_item.item.serial_tracking_mode === 'required' || order.source_receipt_item.item.is_serial_managed) ? 5 : 4 }}</i> 金额与库存影响</h3><div class="amount-grid"><dl><dt>原采购合同金额</dt><dd>¥{{ money(order.original_contract_amount) }}</dd><dt>原采购应付金额</dt><dd>¥{{ money(order.original_payable_amount) }}</dd><dt>换货新增应付金额</dt><dd class="green">¥{{ money(order.exchange_additional_payable_amount) }}</dd></dl><dl><dt>{{ isInventoryExchange ? '原问题库存数量' : '原不合格入库数量' }}</dt><dd>{{ isInventoryExchange ? qty(order.exchange_base_qty) : 0 }} {{ order.base_unit_name_snapshot }}</dd><dt>替换品合格入库数量</dt><dd>{{ order.current_step==='completed'?qty(order.exchange_base_qty):0 }} {{ order.base_unit_name_snapshot }}</dd><dt>入库成本金额</dt><dd>¥{{ money(order.replacement_inventory_cost) }}</dd></dl></div><el-alert title="本次为换货处理，替换品不增加新应付金额，原合同金额不变。" type="success" :closable="false" show-icon /></section>
      <section class="card operation"><h3><i>{{ isInventoryExchange && order.source_receipt_item && order.source_receipt_item.item && (order.source_receipt_item.item.serial_tracking_mode === 'required' || order.source_receipt_item.item.is_serial_managed) ? 6 : 5 }}</i> 当前节点操作（{{ stepText(order.current_step) }}）</h3>
        <el-form v-if="order.current_step==='pending_original_return'" size="small" label-width="115px"><el-alert v-if="!isInventoryExchange" class="pre-stock-tip" title="该不合格品尚未入库，原货从收货/待验区直接退回；无需填写仓库、库位和原序列号。" type="info" :closable="false" show-icon /><el-alert v-else-if="!(order.source_receipt_item && order.source_receipt_item.item && (order.source_receipt_item.item.serial_tracking_mode === 'required' || order.source_receipt_item.item.is_serial_managed))" class="pre-stock-tip" title="该 Item 无需序列号；系统按质量事件绑定的仓库、库位、批次和数量执行原品出库。" type="info" :closable="false" show-icon /><el-form-item label="退回数量"><el-input-number v-model="form.returned_base_qty" :min="0" /></el-form-item><el-form-item label="物流公司"><el-input v-model="form.return_logistics_company" /></el-form-item><el-form-item label="运单号"><el-input v-model="form.return_tracking_no" /></el-form-item><el-form-item v-if="isInventoryExchange && order.source_receipt_item && order.source_receipt_item.item && (order.source_receipt_item.item.serial_tracking_mode === 'required' || order.source_receipt_item.item.is_serial_managed)" label="原品序列号"><el-input v-model="form.original_serial_text" type="textarea" :rows="2" placeholder="引用已入库序列号，每行一个" /></el-form-item></el-form>
        <el-form v-else-if="order.current_step==='supplier_receipt_pending'" size="small" label-width="130px"><el-form-item label="供应商收货确认人"><el-input v-model="form.supplier_receiver" /></el-form-item></el-form>
        <el-form v-else-if="order.current_step==='pending_replacement_shipment'" size="small" label-width="115px"><div class="form-grid"><el-form-item label="供应商补发日期"><el-date-picker v-model="form.replacement_shipped_date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="预计到货时间"><el-date-picker v-model="form.replacement_expected_date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="物流公司"><el-input v-model="form.replacement_logistics_company" /></el-form-item><el-form-item label="运单号"><el-input v-model="form.replacement_tracking_no" /></el-form-item></div></el-form>
        <div v-else-if="order.current_step==='replacement_in_transit'" class="state-tip">替换品运输中。请进入替换品到货单完成到货数量、质量和序列号验收；确认到货后，本单自动进入“替换品待验收”。</div>
        <el-form v-else-if="order.current_step==='pending_replacement_acceptance'" size="small" label-width="100px"><el-form-item label="验收结论"><el-input v-model="form.result_description" type="textarea" :rows="3" /></el-form-item></el-form>
        <div v-else class="state-tip ok">{{ isInventoryExchange ? '换货已完成，金额、库存和原品/替换品编号关系已冻结。' : '换货已完成，原不合格品未入库；金额口径与替换品到货信息已冻结。' }}</div>
        <div v-if="nextAction && $can('purchase.exchange.manage')" class="op-buttons"><input ref="fileInput" type="file" class="hidden-file" @change="uploadProof"><el-button size="small" icon="el-icon-upload2" @click="$refs.fileInput.click()">上传物流/换货凭证</el-button><el-button type="success" size="small" @click="executeNext">{{ nextAction.label }}</el-button></div>
      </section>
    </div>
    <section class="card logs"><h3><i>{{ isInventoryExchange && order.source_receipt_item && order.source_receipt_item.item && (order.source_receipt_item.item.serial_tracking_mode === 'required' || order.source_receipt_item.item.is_serial_managed) ? 7 : 6 }}</i> 操作日志</h3><el-table :data="order.logs || []" border size="mini"><el-table-column label="时间"><template slot-scope="{row}">{{ dateTime(row.created_at) }}</template></el-table-column><el-table-column prop="operator_name" label="操作人" /><el-table-column prop="action" label="操作" /><el-table-column prop="content" label="操作结果" min-width="240" /><el-table-column label="相关单据"><template slot-scope="{row}">{{ row.action === 'create' && isInventoryExchange ? '质量事件：' + val(order.inventory_quality_event,'event_no') : relatedDoc(row) }}</template></el-table-column></el-table></section>

    <el-dialog class="proof-preview-dialog" :title="`凭证预览：${preview.name || ''}`" :visible.sync="preview.visible" width="82%" top="4vh" append-to-body :close-on-click-modal="false" @closed="clearPreview">
      <div v-loading="preview.loading" class="proof-preview-body">
        <img v-if="preview.mode==='image'" :src="preview.url" :alt="preview.name">
        <iframe v-else-if="preview.mode==='pdf' || preview.mode==='office'" :src="preview.url" :title="preview.name" />
        <article v-else-if="preview.mode==='html'" class="document-preview" v-html="preview.html" />
        <pre v-else-if="preview.mode==='text'" class="text-preview">{{ preview.text }}</pre>
        <el-alert v-else-if="preview.error" :title="preview.error" type="warning" :closable="false" show-icon />
        <div v-else class="preview-placeholder">正在读取凭证内容…</div>
      </div>
    </el-dialog>
  </section>
</template>

<script>
import { actionPurchaseExchangeOrder, getPurchaseExchangeOrder, previewPurchaseAttachment, uploadPurchaseAttachment } from '@/api/erp/purchase'
export default { name:'PurchaseExchangeDetail', data(){return{loading:false,order:{},form:{},preview:{visible:false,loading:false,name:'',mode:'',url:'',html:'',text:'',error:''},steps:[{value:'pending_original_return',label:'待原货退回'},{value:'supplier_receipt_pending',label:'供应商已收货'},{value:'pending_replacement_shipment',label:'待补发'},{value:'replacement_in_transit',label:'替换品运输中'},{value:'pending_replacement_acceptance',label:'替换品待验收'},{value:'completed',label:'已完成'}]}}, computed:{isInventoryExchange(){return this.order.source_scope==='inventory_quality'},nextAction(){return {pending_original_return:{value:'register_original_return',label:'登记原货退回'},supplier_receipt_pending:{value:'confirm_supplier_receipt',label:'确认供应商收货'},pending_replacement_shipment:{value:'confirm_replacement_shipment',label:'确认供应商已发货'},pending_replacement_acceptance:{value:'confirm_replacement_acceptance',label:'确认替换品验收完成'}}[this.order.current_step]},originalSerials(){return (this.order.serial_links||[]).map(x=>x.original_serial_no).filter(Boolean).join('、')||'--'},replacementSerials(){return (this.order.serial_links||[]).map(x=>x.replacement_serial_no).filter(Boolean).join('、')||'--'},replacementStatus(){const r=this.order.replacement_receipt;return !r?'--':r.confirm_status==='confirmed'?'已验收':'待收货'}},created(){this.load()},beforeDestroy(){this.clearPreview()},methods:{async load(){this.loading=true;try{const r=await getPurchaseExchangeOrder(this.$route.params.id);this.order=r.data.data||{};this.form={returned_base_qty:Number(this.order.exchange_base_qty||0),return_logistics_company:'',return_tracking_no:'',original_serial_text:'',supplier_receiver:'',replacement_shipped_date:'',replacement_logistics_company:'',replacement_tracking_no:'',replacement_expected_date:'',result_description:''}}finally{this.loading=false}},async executeNext(){if(!this.nextAction)return;const payload={...this.form,action:this.nextAction.value,original_serial_numbers:this.isInventoryExchange?String(this.form.original_serial_text||'').split(/[\n,，;；]+/).map(x=>x.trim()).filter(Boolean):[]};try{await this.$confirm(`确认执行“${this.nextAction.label}”？系统会记录操作人、时间和状态变化。`,'业务确认',{type:'warning'});await actionPurchaseExchangeOrder(this.order.id,payload);this.$message.success('换货单状态已更新');await this.load()}catch(e){if(e!=='cancel'&&e!=='close')this.$message.error(e.userMessage||'操作失败')}},async uploadProof(event){const file=event.target.files&&event.target.files[0];if(!file)return;const form=new FormData();form.append('file',file);form.append('document_type','exchange');form.append('document_id',this.order.id);form.append('attachment_type','delivery_note');try{await uploadPurchaseAttachment(form);this.$message.success('凭证已上传到OSS');await this.load()}catch(e){this.$message.error(e.userMessage||'上传失败')}finally{event.target.value=''}},async previewProof(file){this.clearPreview();this.preview={visible:true,loading:true,name:file.original_name||'未命名凭证',mode:'',url:'',html:'',text:'',error:''};const ext=String(file.original_name||'').split('.').pop().toLowerCase();try{if(ext==='doc'){if(file.url){this.preview.mode='office';this.preview.url=`https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(file.url)}`;return}this.preview.error='该 Word 旧格式文件没有可用于在线预览的公开地址。';return}if(['zip','rar','7z'].includes(ext)){this.preview.error='压缩包不支持在线预览，请上传图片、PDF、Word、Excel 或文本凭证。';return}const response=await previewPurchaseAttachment(file.id);const blob=response.data;if(/^image\//i.test(blob.type)||['jpg','jpeg','png','webp'].includes(ext)){this.preview.mode='image';this.preview.url=URL.createObjectURL(blob);return}if(blob.type==='application/pdf'||ext==='pdf'){this.preview.mode='pdf';this.preview.url=URL.createObjectURL(blob);return}if(['docx'].includes(ext)){const module=await import('mammoth');const mammoth=module.default||module;const result=await mammoth.convertToHtml({arrayBuffer:await blob.arrayBuffer()});this.preview.mode='html';this.preview.html=this.sanitizePreviewHtml(result.value);return}if(['xls','xlsx'].includes(ext)){const XLSX=await import('xlsx');const book=XLSX.read(await blob.arrayBuffer(),{type:'array'});const sheet=book.Sheets[book.SheetNames[0]];this.preview.mode='html';this.preview.html=this.sanitizePreviewHtml(XLSX.utils.sheet_to_html(sheet));return}if(['txt','csv'].includes(ext)||/^text\//i.test(blob.type)){this.preview.mode='text';this.preview.text=await blob.text();return}this.preview.error='该文件类型无法在浏览器中安全预览。'}catch(e){this.preview.error=e.userMessage||'凭证读取失败，请检查文件是否完整。'}finally{this.preview.loading=false}},sanitizePreviewHtml(html){const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('script,style,iframe,object,embed,link,meta').forEach(node=>node.remove());doc.querySelectorAll('*').forEach(node=>Array.from(node.attributes).forEach(attr=>{if(/^on/i.test(attr.name))node.removeAttribute(attr.name)}));return doc.body.innerHTML},clearPreview(){if(this.preview&&this.preview.url&&this.preview.url.startsWith('blob:'))URL.revokeObjectURL(this.preview.url);this.preview={visible:false,loading:false,name:'',mode:'',url:'',html:'',text:'',error:''}},val(o,k){return o&&o[k]||'--'},qty(v){return Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:8})},money(v){return Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})},dateTime(v){return v?String(v).replace('T',' ').slice(0,19):'--'},date(v){return v?String(v).slice(0,10):'--'},stepText(v){return Object.fromEntries(this.steps.map(x=>[x.value,x.label]))[v]||'--'},stepDone(i){const at=this.steps.findIndex(x=>x.value===this.order.current_step);return at>=i},stepTime(v){const m={pending_original_return:'created_at',supplier_receipt_pending:'returned_at',pending_replacement_shipment:'supplier_received_at',replacement_in_transit:'replacement_shipped_at',pending_replacement_acceptance:'replacement_accepted_at',completed:'completed_at'};return this.order[m[v]]?this.dateTime(this.order[m[v]]).slice(0,16):''},relatedDoc(row){if(row.action==='create')return `不合格处理：${this.val(this.order.handling,'handling_no')}`;if(row.action==='confirm_replacement_shipment')return `替换到货：${this.val(this.order.replacement_receipt,'receipt_no')}`;return `换货单：${this.order.exchange_no}`},printPage(){window.print()}}
}
</script>

